using Betta.Attributes;
using Betta.Interfaces;

namespace BenchPlugin
{
    [GrasshopperCollection("Bench", "Mapping")]
    public class RemapPack : IBettaCollection
    {
        // Guid pinned to the pre-refactor id so saved .gh files keep resolving despite the signature change.
        [GrasshopperMethod("Remap", "Remaps a number from a source range to a target range",
            Guid = "368d5f7f-aef6-a49b-f1a5-24f5a5c5d3e2")]
        public (double Result, double Normalized) Remap(
            [GrasshopperParameter("Number")] double number,
            [GrasshopperParameter("Source Min")] double sourceMin,
            [GrasshopperParameter("Source Max")] double sourceMax,
            [GrasshopperParameter("Target Min")] double targetMin,
            [GrasshopperParameter("Target Max")] double targetMax,
            [GrasshopperParameter("Clamp", DefaultValue = false)] bool clamp)
        {
            var t = sourceMax == sourceMin ? 0 : (number - sourceMin) / (sourceMax - sourceMin);
            var result = targetMin + t * (targetMax - targetMin);
            if (clamp)
            {
                var lo = System.Math.Min(targetMin, targetMax);
                var hi = System.Math.Max(targetMin, targetMax);
                result = System.Math.Max(lo, System.Math.Min(hi, result));
            }
            return (result, t);
        }
    }
}
EOF
